// Swept circle vs AABB: returns t of first contact in [0,1], or null.
function sweepContact(px, py, x, y, r, box) {
  const dx = x - px;
  const dy = y - py;
  // Expand box by r
  const minX = box.x - r, minY = box.y - r;
  const maxX = box.x + box.w + r, maxY = box.y + box.h + r;
  let tMin = 0, tMax = 1;
  // X slab
  if (dx === 0) {
    if (px < minX || px > maxX) return null;
  } else {
    let t1 = (minX - px) / dx;
    let t2 = (maxX - px) / dx;
    if (t1 > t2) [t1, t2] = [t2, t1];
    tMin = Math.max(tMin, t1);
    tMax = Math.min(tMax, t2);
    if (tMin > tMax) return null;
  }
  // Y slab
  if (dy === 0) {
    if (py < minY || py > maxY) return null;
  } else {
    let t1 = (minY - py) / dy;
    let t2 = (maxY - py) / dy;
    if (t1 > t2) [t1, t2] = [t2, t1];
    tMin = Math.max(tMin, t1);
    tMax = Math.min(tMax, t2);
    if (tMin > tMax) return null;
  }
  return tMin;
}
```

