export function resolveBricks(state) {
  const { ball, bricks } = state;
  const px = ball.px ?? ball.x;
  const py = ball.py ?? ball.y;

  // Gather all bricks touched along the swept path.
  const hits = [];
  for (const brick of bricks) {
    if (!brick.alive) continue;
    const contact = sweepContact(px, py, ball, brick);
    if (contact) hits.push({ brick, ...contact });
  }
  if (hits.length === 0) return 0;

  // Earliest contact decides the bounce; it is applied exactly once.
  hits.sort((a, b) => a.t - b.t);
  const first = hits[0];
  if (first.faceX && first.faceY) {
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
  } else if (first.faceX) {
    ball.vx = -ball.vx;
  } else {
    ball.vy = -ball.vy;
  }
  pushOut(ball, first, px, py);

  // All bricks touched this pass break.
  let broken = 0;
  for (const hit of hits) {
    if (hit.brick.alive) {
      hit.brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(hit.brick, state.combo);
      broken += 1;
    }
  }
  return broken;
}
```

