// --- Brick collision (issue #1) --------------------------------------------

// Swept circle vs expanded AABB: the ball travelled from (px, py) to its
// current (x, y) during the last step. Returns the time t in [0, 1] of first
// contact along that segment, plus which face(s) were hit, or null on a miss.
// faceX / faceY both true = diagonal corner hit.
function sweepContact(px, py, ball, brick) {
  const { x, y, r } = ball;
  const dx = x - px;
  const dy = y - py;
  const minX = brick.x - r;
  const maxX = brick.x + brick.w + r;
  const minY = brick.y - r;
  const maxY = brick.y + brick.h + r;

  // Entry time through each slab pair (-Infinity when already inside / the
  // slab never contributes a crossing).
  let entryX = -Infinity;
  let entryY = -Infinity;
  let tExit = 1;

  if (dx !== 0) {
    const t1 = (minX - px) / dx;
    const t2 = (maxX - px) / dx;
    entryX = Math.min(t1, t2);
    tExit = Math.min(tExit, Math.max(t1, t2));
  } else if (px < minX || px > maxX) {
    return null;
  }
  if (dy !== 0) {
    const t1 = (minY - py) / dy;
    const t2 = (maxY - py) / dy;
    entryY = Math.min(t1, t2);
    tExit = Math.min(tExit, Math.max(t1, t2));
  } else if (py < minY || py > maxY) {
    return null;
  }

  const inside =
    px >= minX && px <= maxX && py >= minY && py <= maxY;

  if (inside) {
    // Started the step already overlapping: the sweep cannot say which face
    // was entered, so fall back to the penetration heuristic.
    return { t: 0, faceX: penetrationFace(px, py, ball, brick).x, ... };
  }
  ...
}
