export function resolveBricks(state) {
  const { ball, bricks } = state;
  // Fall back to the current position when the step() sweep start was never
  // recorded (fresh ball, direct calls): no movement means no crossing.
  const px = ball.px ?? ball.x;
  const py = ball.py ?? ball.y;

  const hits = [];
  for (const brick of bricks) {
    if (!brick.alive) continue;
    const contact = sweepContact(px, py, ball, brick);
    if (contact !== null) hits.push({ brick, ...contact });
  }
  if (hits.length === 0) return 0;

  // The earliest contact along the swept path decides the bounce. Applied
  // exactly once, even when the seam of the grid overlaps two bricks in the
  // same pass (a double flip would cancel out and let the ball through).
  hits.sort((a, b) => a.t - b.t);
  const first = hits[0];
  const wasVx = ball.vx;
  const wasVy = ball.vy;
  if (first.faceX) ball.vx = -ball.vx;
  if (first.faceY) ball.vy = -ball.vy;

  // Push the ball back out of the brick(s), along the face(s) hit, using the
  // pre-bounce direction to pick the side it came from. Without this the ball
  // still overlaps on the next frame and re-flips forever (sticky bounce).
  const EPS = 0.01;
  if (first.faceX) ball.x = wasVx > 0 ? first.brick.x - ball.r - EPS : first.brick.x + first.brick.w + ball.r + EPS;
  if (first.faceY) ball.y = wasVy > 0 ? first.brick.y - ball.r - EPS : first.brick.y + first.brick.h + ball.r + EPS;

  let broken = 0;
  for (const hit of hits) {
    if (hit.brick.alive) {
      hit.brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(hit.brick, state.combo);
      broken += 1;
    }
  }
  return broken;
}
```

