// --- Brick collision (issue #1) -------------------------------------------

// Swept circle vs expanded AABB. The ball travelled from (px, py) to its
// current (x, y) during the last step; this finds the first contact along that
// segment and the face(s) hit — a plain overlap test at the final position
// misses a fast ball that crosses a brick entirely within one step (at level 6
// a capped 50 ms frame moves the ball 35.5 px, more than the 34 px it takes to
// cross a brick).
// Returns { t, faceX, faceY } with t in [0, 1], or null on a miss.
// faceX / faceY both true = diagonal corner hit.
function sweepContact(px, py, ball, brick) {
  const { x, y, r } = ball;
  const dx = x - px;
  const dy = y - py;
  // The brick expanded by the ball radius: the circle overlaps the brick iff
  // its centre is inside this box.
  const minX = brick.x - r;
  const maxX = brick.x + brick.w + r;
  const minY = brick.y - r;
  const maxY = brick.y + brick.h + r;

  // Slab method: entry time through each pair of planes (-Infinity when the
  // slab never contributes a crossing, e.g. moving straight along it).
  let entryX = -Infinity;
  let entryY = -Infinity;
  let tExit = 1;

  if (dx !== 0) {
    const t1 = (minX - px) / dx;
    const t2 = (maxX - px) / dx;
    entryX = Math.min(t1, t2);
    tExit = Math.min(tExit, Math.max(t1, t2));
  } else if (px < minX || px > maxX) {
    return null; // moving straight, never within the x slab
  }
  if (dy !== 0) {
    const t1 = (minY - py) / dy;
    const t2 = (maxY - py) / dy;
    entryY = Math.min(t1, t2);
    tExit = Math.min(tExit, Math.max(t1, t2));
  } else if (py < minY || py > maxY) {
    return null; // moving straight, never within the y slab
  }

  const inside = px >= minX && px <= maxX && py >= minY && py <= maxY;
  if (inside) {
    // Already overlapping at the start of the step: the sweep cannot tell
    // which face was entered, so fall back to the penetration heuristic.
    const face = penetrationFace(px, py, ball, brick);
    return { t: 0, faceX: face.x, faceY: face.y };
  }

  const tEnter = Math.max(entryX, entryY);
  if (tEnter < 0) return null; // contact happened before this step
  if (tEnter > tExit) return null; // path leaves the box before entering it

  const EPS = 1e-9;
  const faceX = Math.abs(entryX - tEnter) <= EPS;
  const faceY = Math.abs(entryY - tEnter) <= EPS;
  return { t: tEnter, faceX, faceY };
}

// Face hit when the ball centre is inside the expanded box: the axis with the
// smaller penetration is the face that was hit (equal penetrations = corner).
function penetrationFace(px, py, ball, brick) {
  const { r } = ball;
  const minX = brick.x - r;
  const maxX = brick.x + brick.w + r;
  const minY = brick.y - r;
  const maxY = brick.y + brick.h + r;
  const penX = Math.min(px - minX, maxX - px);
  const penY = Math.min(py - minY, maxY - py);
  if (Math.abs(penX - penY) < 1e-9) return { x: true, y: true };
  return penX < penY ? { x: true, y: false } : { x: false, y: true };
}

// Resolves every brick the ball touched during the last step: flips the
// velocity ONCE per the face of the earliest contact (a seam overlaps two
// bricks in the same pass — the grid gap is 8 px and the ball 14 px across —
// and a double flip would cancel out and let the ball through), pushes the
// ball back out of the bricks (otherwise it still overlaps next frame and
// re-flips forever), and breaks every brick hit, scoring as before.
// Pure (no DOM). Returns the number of bricks broken.
export function resolveBricks(state) {
  const { ball, bricks } = state;
  // Fresh balls (relaunch, new level) have no recorded previous position:
  // no movement means nothing can be crossed.
  const px = ball.px ?? ball.x;
  const py = ball.py ?? ball.y;

  const hits = [];
  for (const brick of bricks) {
    if (!brick.alive) continue;
    const contact = sweepContact(px, py, ball, brick);
    if (contact !== null) hits.push({ brick, ...contact });
  }
  if (hits.length === 0) return 0;

  // The earliest contact decides the bounce; it is applied exactly once.
  hits.sort((a, b) => a.t - b.t);
  const first = hits[0];
  const wasVx = ball.vx;
  const wasVy = ball.vy;
  if (first.faceX) ball.vx = -ball.vx;
  if (first.faceY) ball.vy = -ball.vy;

  // Push the ball back out of the brick(s), along the face(s) hit. The
  // pre-bounce direction says which side it came from.
  const EPS = 0.01;
  if (first.faceX) {
    ball.x = wasVx > 0 ? first.brick.x - ball.r - EPS : first.brick.x + first.brick.w + ball.r + EPS;
  }
  if (first.faceY) {
    ball.y = wasVy > 0 ? first.brick.y - ball.r - EPS : first.brick.y + first.brick.h + ball.r + EPS;
  }

  let broken = 0;
  for (const hit of hits) {
    if (hit.brick.alive) {
      hit.brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(hit.brick, state.combo);
      broken += 1;
    }
  }
  return broken;
}

// --- Rendering (DOM) -------------------------------------------------------

// Main render loop: resolves brick collisions (pure) then draws the field.
export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Bricks: bounce + score handled by resolveBricks (see #1), then draw what
  // is left standing.
  resolveBricks(state);
  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }

