import { createState, step, resolveBricks, ballSpeed } from './game/neon.js';
const s = createState(1);
// send the ball straight up at the middle brick of row 2
s.ball.vx = 0; s.ball.vy = -ballSpeed(1);
s.ball.x = 320;
let bounces = 0, broken = 0, minY = 1e9;
for (let i = 0; i < 400; i++) {
  const lost = step(s, 1/60);
  const before = s.ball.vy;
  broken += resolveBricks(s);
  if (s.ball.vy !== before) bounces++;
  minY = Math.min(minY, s.ball.y);
  if (lost) break;
}
console.log('bricks broken:', broken, '| direction flips at bricks:', bounces, '| min ball y:', minY.toFixed(1));
const initial = createState(1).bricks.length;
console.log('remaining:', s.bricks.filter(b=>b.alive).length, '/', initial, '| score:', s.score, '| combo:', s.combo);
